import React, { useEffect, useState, useRef } from 'react';
import { Scale, Copy, Share2, Printer, Bookmark, ZoomIn, ZoomOut, Check } from 'lucide-react';

interface DocumentViewerProps {
  activeArticleId: string | null;
  hasSearched: boolean;
  onQuickSearch: (query: string) => void;
}

export function DocumentViewer({ activeArticleId, hasSearched, onQuickSearch }: DocumentViewerProps) {
  const [highlightedId, setHighlightedId] = useState<string | null>(null);
  const [isFading, setIsFading] = useState(false);
  const [fontSize, setFontSize] = useState(16);
  const [copyTooltip, setCopyTooltip] = useState<{ x: number, y: number, text: string, visible: boolean, copied: boolean }>({ x: 0, y: 0, text: '', visible: false, copied: false });
  const [scrollProgress, setScrollProgress] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);

  // Smooth Scroll & Highlight Logic
  useEffect(() => {
    if (!activeArticleId) return;
    const el = document.getElementById(activeArticleId);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      setHighlightedId(activeArticleId);
      setIsFading(false);
      
      const fadeTimer = setTimeout(() => setIsFading(true), 2500);
      const removeTimer = setTimeout(() => setHighlightedId(null), 3500);
      
      return () => { clearTimeout(fadeTimer); clearTimeout(removeTimer); };
    }
  }, [activeArticleId]);

  // Contextual Copy Logic
  useEffect(() => {
    const handleSelection = () => {
      const selection = window.getSelection();
      if (selection && selection.toString().trim().length > 0 && containerRef.current?.contains(selection.anchorNode)) {
        const range = selection.getRangeAt(0);
        const rect = range.getBoundingClientRect();
        const containerRect = containerRef.current.getBoundingClientRect();
        
        setCopyTooltip({
          x: rect.left + rect.width / 2 - containerRect.left,
          y: rect.top - containerRect.top - 40,
          text: selection.toString(),
          visible: true,
          copied: false
        });
      } else {
        if (!copyTooltip.copied) setCopyTooltip(prev => ({ ...prev, visible: false }));
      }
    };

    document.addEventListener('selectionchange', handleSelection);
    return () => document.removeEventListener('selectionchange', handleSelection);
  }, [copyTooltip.copied]);

  const handleCopy = () => {
    const textToCopy = `${copyTooltip.text}\n[المصدر: قانون المعاملات المدنية العماني]`;
    navigator.clipboard.writeText(textToCopy);
    setCopyTooltip(prev => ({ ...prev, copied: true }));
    setTimeout(() => {
      setCopyTooltip(prev => ({ ...prev, visible: false, copied: false }));
      window.getSelection()?.removeAllRanges();
    }, 1500);
  };

  const handleScroll = () => {
    if (!containerRef.current) return;
    const { scrollTop, scrollHeight, clientHeight } = containerRef.current;
    const progress = (scrollTop / (scrollHeight - clientHeight)) * 100;
    setScrollProgress(progress);
  };

  if (!hasSearched) {
    return (
      <div className="flex flex-col items-center justify-center h-full bg-slate-50">
        <Scale className="w-32 h-32 text-slate-200 mb-6" />
        <h2 className="text-2xl font-semibold text-slate-400 mb-3">ابدأ بحثك القانوني</h2>
        <p className="text-sm text-slate-400 text-center max-w-sm mb-10 leading-relaxed">
          اكتب سؤالاً بلغة طبيعية في الجانب الأيمن وسيقوم النظام باسترجاع المواد القانونية والمبادئ القضائية ذات الصلة
        </p>
        
        <div className="flex flex-col gap-3 w-full max-w-md">
          <button onClick={() => onQuickSearch("شروط الفسخ في عقود المقاولة")} className="bg-white border border-gray-200 hover:border-blue-300 hover:bg-blue-50 text-slate-600 rounded-lg py-3 px-4 text-sm transition-colors text-right shadow-sm">
            "شروط الفسخ في عقود المقاولة"
          </button>
          <button onClick={() => onQuickSearch("تعويض العامل عند الفصل التعسفي")} className="bg-white border border-gray-200 hover:border-blue-300 hover:bg-blue-50 text-slate-600 rounded-lg py-3 px-4 text-sm transition-colors text-right shadow-sm">
            "تعويض العامل عند الفصل التعسفي"
          </button>
          <button onClick={() => onQuickSearch("أركان عقد الإيجار التجاري")} className="bg-white border border-gray-200 hover:border-blue-300 hover:bg-blue-50 text-slate-600 rounded-lg py-3 px-4 text-sm transition-colors text-right shadow-sm">
            "أركان عقد الإيجار التجاري"
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-slate-50 relative" ref={containerRef} onScroll={handleScroll}>
      {/* Reading Progress Bar */}
      <div className="absolute top-0 left-0 right-0 h-0.5 bg-gray-200 z-50">
        <div className="h-full bg-blue-600 transition-all duration-150" style={{ width: `${scrollProgress}%` }}></div>
      </div>

      {/* Mini-Toolbar */}
      <div className="sticky top-0 bg-white/80 backdrop-blur-sm border-b border-gray-100 z-10 px-8 py-3 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <span className="text-xs font-semibold text-slate-500 bg-slate-100 px-3 py-1.5 rounded-md">
            قانون المعاملات المدنية العماني
          </span>
        </div>
        
        <div className="flex items-center gap-1">
          <button onClick={() => setFontSize(p => Math.min(p + 2, 24))} className="p-2 text-slate-500 hover:text-navy-900 hover:bg-slate-100 rounded-md transition-colors" title="تكبير الخط">
            <ZoomIn className="w-4 h-4" />
          </button>
          <button onClick={() => setFontSize(p => Math.max(p - 2, 12))} className="p-2 text-slate-500 hover:text-navy-900 hover:bg-slate-100 rounded-md transition-colors" title="تصغير الخط">
            <ZoomOut className="w-4 h-4" />
          </button>
          <div className="w-px h-5 bg-slate-200 mx-2"></div>
          <button className="p-2 text-slate-500 hover:text-navy-900 hover:bg-slate-100 rounded-md transition-colors" title="نسخ المستند">
            <Copy className="w-4 h-4" />
          </button>
          <button className="p-2 text-slate-500 hover:text-navy-900 hover:bg-slate-100 rounded-md transition-colors" title="مشاركة">
            <Share2 className="w-4 h-4" />
          </button>
          <button className="p-2 text-slate-500 hover:text-navy-900 hover:bg-slate-100 rounded-md transition-colors" title="حفظ في القضية">
            <Bookmark className="w-4 h-4" />
          </button>
          <button className="p-2 text-slate-500 hover:text-navy-900 hover:bg-slate-100 rounded-md transition-colors" title="طباعة">
            <Printer className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Document Content */}
      <div className="flex-1 overflow-y-auto p-12 bg-white mx-8 my-8 shadow-sm rounded-sm relative">
        {/* Contextual Copy Tooltip */}
        {copyTooltip.visible && (
          <div 
            className="absolute z-50 bg-gray-900 text-white text-xs rounded-md shadow-xl px-3 py-2 flex items-center gap-2 cursor-pointer hover:bg-gray-800 transition-colors transform -translate-x-1/2 animate-fade-in"
            style={{ top: copyTooltip.y, left: copyTooltip.x }}
            onClick={handleCopy}
          >
            {copyTooltip.copied ? (
              <>
                <Check className="w-3 h-3 text-green-400" />
                <span className="text-green-400">تم النسخ</span>
              </>
            ) : (
              <>
                <Copy className="w-3 h-3" />
                نسخ مع المرجع
              </>
            )}
          </div>
        )}

        <div className="max-w-3xl mx-auto" style={{ fontSize: `${fontSize}px` }}>
          
          <div className="text-center mb-16">
            <h1 className="text-2xl font-bold text-navy-900 mb-2">قانون المعاملات المدنية</h1>
            <p className="text-slate-500">الصادر بالمرسوم السلطاني رقم 29 / 2013</p>
          </div>

          {/* Article 152 */}
          <div 
            id="article-152" 
            className={`mb-12 p-4 -mx-4 rounded-lg transition-colors duration-500 ${
              highlightedId === 'article-152' ? (isFading ? 'bg-transparent' : 'bg-yellow-100') : 'bg-transparent'
            }`}
          >
            <h3 className="text-lg font-bold text-navy-900 border-b border-gray-200 pb-2 mb-4">
              المادة (152)
            </h3>
            <p className="font-light text-slate-800 leading-loose text-justify">
              في العقود الملزمة للجانبين إذا لم يوف أحد المتعاقدين بالتزامه جاز للمتعاقد الآخر بعد إعذاره المدين أن يطالب بتنفيذ العقد أو بفسخه مع التعويض في الحالتين إن كان له مقتض.
              ويجوز للقاضي أن يمنح المدين أجلا إذا اقتضت الظروف ذلك كما يجوز له أن يرفض الفسخ إذا كان ما لم يوف به المدين قليل الأهمية بالنسبة إلى الالتزام في جملته.
            </p>
          </div>

          {/* Article 153 */}
          <div 
            id="article-153" 
            className={`mb-12 p-4 -mx-4 rounded-lg transition-colors duration-500 ${
              highlightedId === 'article-153' ? (isFading ? 'bg-transparent' : 'bg-yellow-100') : 'bg-transparent'
            }`}
          >
            <h3 className="text-lg font-bold text-navy-900 border-b border-gray-200 pb-2 mb-4">
              المادة (153)
            </h3>
            <p className="font-light text-slate-800 leading-loose text-justify">
              يجوز الاتفاق على أن يعتبر العقد مفسوخا من تلقاء نفسه دون حاجة إلى حكم قضائي عند عدم الوفاء بالالتزامات الناشئة عنه، وهذا الاتفاق لا يعفي من الإعذار إلا إذا اتفق المتعاقدان صراحة على الإعفاء منه.
            </p>
          </div>
          
          {/* Mock content to allow scrolling */}
          {Array.from({ length: 10 }).map((_, i) => (
             <div key={i} className="mb-12 p-4 -mx-4">
               <h3 className="text-lg font-bold text-navy-900 border-b border-gray-200 pb-2 mb-4">
                 المادة ({154 + i})
               </h3>
               <p className="font-light text-slate-800 leading-loose text-justify">
                 نص المادة القانونية المحاكى لعرض تأثير التمرير والقراءة. يجب أن يكون النص طويلاً بما يكفي ليأخذ مساحة على الشاشة ويثبت فاعلية القفز الاستهدافي بين المواد المتعددة في القانون المدني أو التجاري.
               </p>
             </div>
          ))}

        </div>
      </div>
    </div>
  );
}
