'use client';

import { useState } from "react";
import { SplitViewLayout } from "@/components/layout/SplitViewLayout";
import { SearchSidebar } from "@/components/search/SearchSidebar";
import { DocumentViewer } from "@/components/search/DocumentViewer";

export default function SearchPage() {
  const [activeArticleId, setActiveArticleId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);

  const handleSearch = (query: string) => {
    setSearchQuery(query);
    setIsLoading(true);
    setHasSearched(true);
    
    // Simulate RAG retrieval delay
    setTimeout(() => {
      setSearchResults([
        {
          id: 'res-1',
          summary: 'يعتبر التأخير في تسليم الموقع سبباً لفسخ العقد وفقاً للقانون العماني، شريطة إثبات الضرر الفعلي، وتوافر شروط الفسخ المحددة في القانون.',
          confidence: 95,
          citations: [
            { id: 'article-152', title: 'المادة 152', source: 'قانون المعاملات المدنية' },
            { id: 'article-153', title: 'المادة 153', source: 'قانون المعاملات المدنية' }
          ]
        }
      ]);
      setIsLoading(false);
    }, 2500); // 2.5s for the 3 stages of skeleton
  };

  return (
    <SplitViewLayout 
      sidebar={
        <SearchSidebar 
          onArticleClick={setActiveArticleId}
          onSearch={handleSearch}
          isLoading={isLoading}
          searchResults={searchResults}
          searchQuery={searchQuery}
        />
      } 
      content={
        <DocumentViewer 
          activeArticleId={activeArticleId} 
          hasSearched={hasSearched}
          onQuickSearch={handleSearch}
        />
      } 
    />
  );
}
